import { useState, useEffect, useRef } from "react";

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Playfair+Display:ital,wght@0,700;0,900;1,400&family=IBM+Plex+Mono:wght@400;700&family=Righteous&family=DM+Mono:wght@400;500&family=Unbounded:wght@700;900&family=Instrument+Serif:ital@1&family=Space+Grotesk:wght@300;400;700&family=Syne:wght@700;800&family=Fraunces:ital,wght@1,700&display=swap');
*{box-sizing:border-box;margin:0;padding:0;}
body{background:#0A0A0A;font-family:'DM Mono',monospace;color:#EEE;}
::-webkit-scrollbar{width:2px;height:2px;}
::-webkit-scrollbar-thumb{background:#2A2A2A;}
button,input{outline:none;cursor:pointer;}
@keyframes spin{from{transform:rotate(0)}to{transform:rotate(360deg)}}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:0.4}}
@keyframes blink{0%,100%{opacity:1}50%{opacity:0}}
@keyframes aurora{0%,100%{background-position:0% 50%}50%{background-position:100% 50%}}
@keyframes neonPulse{0%,100%{text-shadow:0 0 4px #ff2d78,0 0 12px #ff2d7844}50%{text-shadow:0 0 2px #ff2d78}}
@keyframes scanV{from{top:-100%}to{top:100%}}
@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
@keyframes breathe{0%,100%{transform:scale(1)}50%{transform:scale(1.05)}}
@keyframes dotB{0%,80%,100%{transform:translateY(0)}40%{transform:translateY(-5px)}}
`;

