  Playful:   ()=> {const[h,setH]=useState(false);return <div style={{background:"linear-gradient(135deg,#FFF0F5,#F0F5FF)",height:"100%",display:"flex",alignItems:"center",justifyContent:"center"}}><button onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)} style={{background:h?"#FF6B9D":"transparent",border:"2px solid #FF6B9D",borderRadius:50,padding:"7px 18px",color:h?"white":"#FF6B9D",fontFamily:"'Righteous',sans-serif",fontSize:9,letterSpacing:1,cursor:"pointer",transition:"all 0.2s",boxShadow:h?"0 4px 14px #FF6B9D66":"none"}}>Create ✦</button></div>;},
  Luxury:    ()=> <div style={{background:"#FAFAF8",height:"100%",display:"flex",alignItems:"center",justifyContent:"center"}}><button style={{background:"transparent",border:"1px solid #C4A96A",padding:"7px 20px",color:"#C4A96A",fontFamily:"'Fraunces',serif",fontStyle:"italic",fontSize:9,letterSpacing:3,cursor:"pointer"}}>Discover</button></div>,
  Cyberpunk: ()=> {const[h,setH]=useState(false);return <div style={{background:"#0A0A12",height:"100%",display:"flex",alignItems:"center",justifyContent:"center"}}><button onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)} style={{background:h?"#00FFFF22":"transparent",border:"1px solid #00FFFF",padding:"8px 18px",color:"#00FFFF",fontFamily:"'IBM Plex Mono',monospace",fontSize:9,letterSpacing:3,cursor:"pointer",transition:"all 0.2s",boxShadow:h?"0 0 16px #00FFFF44":"none",clipPath:"polygon(4px 0%,100% 0%,calc(100% - 4px) 100%,0% 100%)"}}>EXECUTE</button></div>;},
